import { z } from "zod";

export const orderLineSchema = z
  .object({
    menuItemId: z.string().uuid(),
    qty: z.number().int().min(1).max(99),
  })
  .strict();

// POST /api/orders body: the cart. businessId, prices and the table come from the guest session.
export const submitOrderSchema = z
  .object({
    items: z.array(orderLineSchema).min(1).max(50),
  })
  .strict();

// Guest token from `Authorization: Bearer <token>` (issued by POST /api/guest-sessions).
export const guestTokenSchema = z.string().regex(/^[0-9a-f]{64}$/);

// Idempotency-Key header, generated by the phone once per cart submission.
export const idempotencyKeySchema = z.string().trim().min(1).max(255);

export type SubmitOrderBody = z.infer<typeof submitOrderSchema>;
